INSERT INTO public.authors (id, full_name, sort_name, biography, created_at, updated_at) VALUES ('fbacfd7c-81bf-4fe3-a063-a4e148874750', 'Nguyen Nhat Anh', 'Anh, Nguyen Nhat', 'Nguyen Nhat Anh (1954-2021) la nha van, nhac si Vietnam. Tac gia cua "Cho toi xin mot ve di tuoi tho", "Mat toc ngan, mat ngu dai", "Benh gieng cua Beethoven".', '2026-09-08 06:40:42.772+00', '2026-09-08 06:40:42.772+00') ON CONFLICT DO NOTHING;
INSERT INTO public.authors (id, full_name, sort_name, biography, created_at, updated_at) VALUES ('95322be5-03dc-4805-a4ac-12d9129ef36c', 'Nam Cao', 'Cao, Nam', 'Nam Cao (1915-1962) la nha van noi tieng cua Vietnam, tac gia cua "So do" va "Chiec la cuoi cung". Op tan van hoc hien thuc, chu tap trung vao cuoc song nhan vat nong thon va giai cap cong nhan nho trong xa hoi phong kien.', '2026-09-08 06:40:42.772+00', '2026-09-08 06:40:42.772+00') ON CONFLICT DO NOTHING;
INSERT INTO public.authors (id, full_name, sort_name, biography, created_at, updated_at) VALUES ('b5b3d647-e7c6-4104-a667-6645f636fc62', 'To Hoai', 'Hoai, To', 'To Hoai (1920-2010) la nha van noi tieng, tac gia cua "Tam Cam", "Me Chim", "Dua tre con ra chon". Tap trung vao doi song nong thon va thanh thi Vietnam.', '2026-09-08 06:40:42.772+00', '2026-09-08 06:40:42.772+00') ON CONFLICT DO NOTHING;
INSERT INTO public.authors (id, full_name, sort_name, biography, created_at, updated_at) VALUES ('decb52f7-dfe9-4d01-82da-85e30f15193d', 'Gabriel Garcia Marquez', 'Marquez, Gabriel Garcia', 'Gabriel Garcia Marquez (1927-2014) la nha van Colombia, giai thuong Nobel Van hoc 1982. Tac gia cua "Troi nam tram", "Tinh yeu trong mua mua", "Bi mat cua Hoang ha".', '2026-09-08 06:40:42.772+00', '2026-09-08 06:40:42.772+00') ON CONFLICT DO NOTHING;
INSERT INTO public.authors (id, full_name, sort_name, biography, created_at, updated_at) VALUES ('b4c3c3d2-c841-44df-a7bb-5f70cb1125df', 'Tran Dang Khoa', 'Khoa, Tran Dang', 'Tran Dang Khoa la nhac si, nhap khau noi tieng cua Vietnam. Tieu bieu voi "Bai ca ru ngay", "Cua so nho", "Con mua ngang qua".', '2026-09-08 06:40:42.772+00', '2026-09-08 06:40:42.772+00') ON CONFLICT DO NOTHING;
INSERT INTO public.authors (id, full_name, sort_name, biography, created_at, updated_at) VALUES ('360e807c-ec04-4e30-9463-23e32454ac5b', 'Haruki Murakami', 'Murakami, Haruki', 'Haruki Murakami (1949-) la nha van Nhat Ban noi tieng the gioi. Tac pham noi bat: "Norwegian Wood", "Kafka ben bo song", "1Q84". Phong cach viet day am tinh, hai nghi, pha tram giua that va mo.', '2026-09-08 06:40:42.772+00', '2026-09-08 06:40:42.772+00') ON CONFLICT DO NOTHING;
INSERT INTO public.authors (id, full_name, sort_name, biography, created_at, updated_at) VALUES ('9bc730ec-96f2-4646-893e-b3df25c41933', 'Ngo Tat Lu', 'Lu, Ngo Tat', 'Ngo Tat Lu (1894-1963) la nha van lon cua van hoc Viet Nam hien dai. Tac gia cua "Toi thay hoa vang tren co xanh", "Ngot ran nuoc dog", "Kieu Ba La".', '2026-09-08 06:40:42.772+00', '2026-09-08 06:40:42.772+00') ON CONFLICT DO NOTHING;
